from langchain.evaluation import load_evaluator
from langchain_openai import ChatOpenAI
from langchain.evaluation import EvaluatorType

model_key=""
api_gateway_url=""

# LLM as a Judge
llm_model = "qwen3-vllm"

llm = ChatOpenAI( model=llm_model, temperature=0, 
                   api_key=model_key, base_url=api_gateway_url)


evaluator = load_evaluator(EvaluatorType.CRITERIA, criteria="conciseness", llm=llm,)


eval_result = evaluator.evaluate_strings(
    # this is the prediction we want to evaluate aka generated by my target LLM
    prediction="What's 2+2? That's an elementary question. The answer you're looking for is that two and two is four.",
    input="What's 2+2?",
)

print(eval_result)

import json
print(json.dumps(eval_result, indent=2, default=str))



evaluator = load_evaluator("labeled_criteria", criteria="correctness", llm=llm,)

# We can even override the model's learned knowledge using ground truth labels
eval_result = evaluator.evaluate_strings(
    input="What is the capital of the Australia?",
    # this is the prediction we want to evaluate aka generated by my target LLM
    prediction="Canberra",
    reference="The capital of Australia is Canberra.",
)
print(json.dumps(eval_result, indent=2, default=str))
# # print(f'With ground truth: {eval_result["score"]}')


